export const charts=['bars','pie','dots','wordcloud'];
export const liveChart=(exam,q)=>q.presentationChart&&q.presentationChart!=='inherit'?q.presentationChart:(exam.presentation?.chart||'bars');
export function validateLiveConfig(e){if(e.mode!==undefined&&!['assessment','live'].includes(e.mode))return false;if(e.presentation&&(!['count','percent'].includes(e.presentation.value)||!charts.includes(e.presentation.chart)))return false;for(const q of e.questions||[]){if(!q||typeof q!=='object')return false;if(q.presentationChart!==undefined&&!['inherit',...charts].includes(q.presentationChart))return false;if(e.mode==='live'){if(!['choice','multiple','open'].includes(q.type)||q.responseFormat==='code')return false;if(liveChart(e,q)==='wordcloud'&&q.type!=='open')return false;}}return true;}
export function emptyAggregate(q){return{responseCount:0,optionCounts:(q.options||[]).map(()=>0),entries:[]};}
export function aggregateResponse(q,aggregate,answer){const a=structuredClone(aggregate||emptyAggregate(q));a.responseCount++;if(q.type==='choice')a.optionCounts[answer]++;else if(q.type==='multiple')for(const n of answer)a.optionCounts[n]++;else{const text=answer.trim().replace(/\s+/g,' '),key=text.toLocaleLowerCase('pt-BR');const row=a.entries.find(x=>x.key===key);if(row)row.count++;else a.entries.push({key,text,count:1});}return a;}
export function liveSeries(q,a,chart){const total=a?.responseCount||0;if(chart==='wordcloud'){const words=new Map();for(const row of a?.entries||[]){const unique=new Set(row.text.toLocaleLowerCase('pt-BR').match(/[\p{L}\p{N}]+/gu)||[]);for(const word of unique)if(word.length>1)words.set(word,(words.get(word)||0)+row.count);}return[...words].map(([label,count])=>({label,count,percent:total?count/total*100:0})).sort((x,y)=>y.count-x.count||x.label.localeCompare(y.label)).slice(0,50);}let series=q.options?q.options.map((label,i)=>({label,count:a?.optionCounts?.[i]||0})):(a?.entries||[]).map(x=>({label:x.text,count:x.count}));if(!q.options&&series.length>20){series.sort((x,y)=>y.count-x.count);series=[...series.slice(0,19),{label:'Outras respostas',count:series.slice(19).reduce((s,x)=>s+x.count,0)}];}const marks=series.reduce((s,x)=>s+x.count,0);return series.map(x=>({...x,percent:total?x.count/total*100:0,sharePercent:marks?x.count/marks*100:0}));}
